import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { randomBytes } from 'node:crypto';

// Books live in memory and every change is written to a JSON file.
// Changes run one at a time, so two quick requests can't overwrite each other,
// and the file is written to a temp file first and then renamed into place,
// so a crash halfway through a write can't leave a broken file behind.
export async function createStore(filePath) {
  let books = await load(filePath);
  let queue = Promise.resolve();

  function update(change) {
    const run = queue.then(async () => {
      const next = structuredClone(books);
      const result = change(next);
      await save(filePath, next);
      books = next;
      return result;
    });
    // Keep the queue going even if this change fails.
    queue = run.catch(() => {});
    return run;
  }

  return {
    list() {
      return structuredClone(books);
    },

    get(id) {
      const book = books.find((b) => b.id === id);
      return book ? structuredClone(book) : undefined;
    },

    add({ title, author = '', notes = '' }) {
      return update((all) => {
        const book = {
          id: newId(),
          title,
          author,
          notes,
          status: 'reading',
          addedAt: new Date().toISOString(),
          finishedAt: null,
        };
        all.push(book);
        return structuredClone(book);
      });
    },

    finish(id) {
      return update((all) => {
        const book = all.find((b) => b.id === id);
        if (!book) return undefined;
        if (book.status !== 'finished') {
          book.status = 'finished';
          book.finishedAt = new Date().toISOString();
        }
        return structuredClone(book);
      });
    },

    setNotes(id, notes) {
      return update((all) => {
        const book = all.find((b) => b.id === id);
        if (!book) return undefined;
        book.notes = notes;
        return structuredClone(book);
      });
    },
  };
}

async function load(filePath) {
  let text;
  try {
    text = await readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    // Refuse to start rather than risk overwriting the user's books.
    throw new Error(`${filePath} is not valid JSON: ${err.message}`);
  }
  if (!Array.isArray(data)) {
    throw new Error(`${filePath} should contain a JSON array of books`);
  }
  return data;
}

async function save(filePath, books) {
  await mkdir(dirname(filePath), { recursive: true });
  const tmp = `${filePath}.${process.pid}.tmp`;
  await writeFile(tmp, JSON.stringify(books, null, 2) + '\n');
  await rename(tmp, filePath);
}

// Short random ids, e.g. "k3xq9t2m1bz8". Hard to guess, easy to paste in a link.
function newId() {
  return randomBytes(9).toString('base64url').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 12)
    || randomBytes(6).toString('hex');
}

