const MAX_BODY_BYTES = 100_000;

export function createApp(store) {
  return async function handle(req, res) {
    try {
      await route(store, req, res);
    } catch (err) {
      if (err instanceof HttpError) {
        sendPage(res, err.status, page('Oops', `<p>${escape(err.message)}</p><p><a href="/">Back to my books</a></p>`));
        return;
      }
      console.error(err);
      sendPage(res, 500, page('Something went wrong', '<p>Something went wrong. Please try again.</p><p><a href="/">Back to my books</a></p>'));
    }
  };
}

async function route(store, req, res) {
  const { pathname } = new URL(req.url, 'http://localhost');
  const method = req.method === 'HEAD' ? 'GET' : req.method;

  if (pathname === '/') {
    allow(method, 'GET');
    sendPage(res, 200, homePage(store.list()));
    return;
  }

  if (pathname === '/books') {
    allow(method, 'POST');
    const form = await readForm(req);
    const input = {
      title: clean(form.get('title')),
      author: clean(form.get('author')),
      notes: cleanNotes(form.get('notes')),
    };
    if (!input.title) {
      sendPage(res, 400, homePage(store.list(), { error: 'Please give the book a title.', values: input }));
      return;
    }
    await store.add(input);
    redirect(res, '/');
    return;
  }

  const match = pathname.match(/^\/books\/([a-z0-9]+)(\/finish|\/notes)?$/);
  if (match) {
    const [, id, action] = match;
    const book = store.get(id);
    if (!book) throw new HttpError(404, "That book isn't here. It may have been a mistyped link.");

    if (!action) {
      allow(method, 'GET');
      sendPage(res, 200, bookPage(book, req));
      return;
    }

    allow(method, 'POST');
    const form = await readForm(req);
    if (action === '/finish') {
      await store.finish(id);
      redirect(res, form.get('back') === 'home' ? '/' : `/books/${id}`);
    } else {
      await store.setNotes(id, cleanNotes(form.get('notes')));
      redirect(res, `/books/${id}`);
    }
    return;
  }

  throw new HttpError(404, "There's no page here.");
}

// ---------- pages ----------

function homePage(books, { error = '', values = {} } = {}) {
  const reading = books
    .filter((b) => b.status === 'reading')
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  const readingList = reading.length
    ? `<ul class="books">${reading.map((b) => `
        <li>
          ${bookLink(b)}
          <form method="post" action="/books/${b.id}/finish">
            <input type="hidden" name="back" value="home">
            <button type="submit">Mark finished</button>
          </form>
        </li>`).join('')}</ul>`
    : '<p class="empty">Nothing on the go. Add a book below.</p>';

  const finishedList = finished.length
    ? `<ul class="books">${finished.map((b) => `
        <li>
          ${bookLink(b)}
          <span class="meta">finished ${formatDate(b.finishedAt)}</span>
        </li>`).join('')}</ul>`
    : '<p class="empty">No finished books yet.</p>';

  return page('My books', `
    <h1>My books</h1>

    <h2>Currently reading</h2>
    ${readingList}

    <h2>Finished</h2>
    ${finishedList}

    <h2 id="add">Add a book</h2>
    ${error ? `<p class="error" role="alert">${escape(error)}</p>` : ''}
    <form method="post" action="/books" class="add">
      <label>Title <input name="title" required maxlength="300" value="${escape(values.title ?? '')}"></label>
      <label>Author <input name="author" maxlength="300" value="${escape(values.author ?? '')}"></label>
      <label>Notes <textarea name="notes" rows="4">${escape(values.notes ?? '')}</textarea></label>
      <button type="submit">Add book</button>
    </form>
  `);
}

function bookPage(book, req) {
  const link = shareLink(req, book.id);
  const status = book.status === 'finished'
    ? `Finished ${formatDate(book.finishedAt)}`
    : `Reading since ${formatDate(book.addedAt)}`;

  return page(book.title, `
    <p><a href="/">&larr; My books</a></p>

    <h1>${escape(book.title)}</h1>
    <p class="author">${book.author ? `by ${escape(book.author)}` : '<span class="meta">Author unknown</span>'}</p>
    <p class="meta">${status}</p>

    ${book.status === 'reading' ? `
      <form method="post" action="/books/${book.id}/finish">
        <button type="submit">Mark finished</button>
      </form>` : ''}

    <h2>Notes</h2>
    ${book.notes ? `<div class="notes">${escape(book.notes)}</div>` : '<p class="empty">No notes yet.</p>'}

    <details>
      <summary>Edit notes</summary>
      <form method="post" action="/books/${book.id}/notes">
        <textarea name="notes" rows="8" aria-label="Notes">${escape(book.notes)}</textarea>
        <button type="submit">Save notes</button>
      </form>
    </details>

    <h2>Share</h2>
    <p>Send this link to share this book:</p>
    <input class="share" readonly value="${escape(link)}" aria-label="Link to this book" onfocus="this.select()">
  `);
}

function bookLink(book) {
  const author = book.author ? ` <span class="meta">by ${escape(book.author)}</span>` : '';
  return `<span><a href="/books/${book.id}">${escape(book.title)}</a>${author}</span>`;
}

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  h1 { margin-bottom: 0.25rem; }
  h2 { margin-top: 2rem; font-size: 1.15rem; }
  a { color: #1a5fb4; }
  .books { list-style: none; padding: 0; }
  .books li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 0.5rem 0; border-bottom: 1px solid #eee; }
  .books form { margin: 0; }
  .meta, .empty { color: #666; }
  .author { font-size: 1.1rem; margin: 0; }
  .notes { white-space: pre-wrap; background: #f7f7f5; padding: 0.75rem 1rem; border-radius: 6px; }
  .error { color: #a51d2d; font-weight: 600; }
  .add label { display: block; margin-bottom: 0.75rem; }
  input, textarea { display: block; width: 100%; box-sizing: border-box; padding: 0.4rem; font: inherit; margin-top: 0.2rem; }
  button { font: inherit; padding: 0.3rem 0.8rem; cursor: pointer; }
  details { margin-top: 1rem; }
  details textarea { margin-bottom: 0.5rem; }
</style>
</head>
<body>
${body}
</body>
</html>
`;
}

// ---------- helpers ----------

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

function allow(method, expected) {
  if (method !== expected) throw new HttpError(405, 'That action is not allowed here.');
}

function sendPage(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; script-src-attr 'unsafe-inline'; form-action 'self'",
    'X-Content-Type-Options': 'nosniff',
  });
  res.end(html);
}

function redirect(res, location) {
  // 303 so the browser follows with a GET; refreshing won't resubmit the form.
  res.writeHead(303, { Location: location });
  res.end();
}

async function readForm(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new HttpError(413, 'That was too much text to save in one go.');
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function clean(value) {
  return (value ?? '').replace(/\s+/g, ' ').trim().slice(0, 300);
}

function cleanNotes(value) {
  return (value ?? '').replace(/\r\n/g, '\n').trim();
}

function shareLink(req, id) {
  const host = req.headers.host || 'localhost';
  return `http://${host}/books/${id}`;
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

function escape(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

