import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createServer } from 'node:http';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createStore } from '../src/store.js';
import { createApp } from '../src/app.js';

let dir;
let dataFile;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  dataFile = join(dir, 'nested', 'books.json');
});

afterEach(async () => {
  await rm(dir, { recursive: true, force: true });
});

describe('store', () => {
  it('starts empty when there is no file yet', async () => {
    const store = await createStore(dataFile);
    expect(store.list()).toEqual([]);
  });

  it('keeps books after a restart', async () => {
    const first = await createStore(dataFile);
    const book = await first.add({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' });
    await first.finish(book.id);

    const second = await createStore(dataFile);
    const saved = second.get(book.id);
    expect(saved).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.', status: 'finished' });
    expect(saved.finishedAt).toBeTruthy();
  });

  it('does not lose books when several are added at once', async () => {
    const store = await createStore(dataFile);
    await Promise.all(Array.from({ length: 20 }, (_, i) => store.add({ title: `Book ${i}` })));
    const reloaded = await createStore(dataFile);
    expect(reloaded.list()).toHaveLength(20);
  });

  it('refuses to start on a broken file instead of overwriting it', async () => {
    await writeFile(join(dir, 'broken.json'), '{ not json');
    await expect(createStore(join(dir, 'broken.json'))).rejects.toThrow(/not valid JSON/);
    expect(await readFile(join(dir, 'broken.json'), 'utf8')).toBe('{ not json');
  });
});

describe('app', () => {
  let server;
  let base;
  let store;

  beforeEach(async () => {
    store = await createStore(dataFile);
    server = createServer(createApp(store));
    await new Promise((r) => server.listen(0, '127.0.0.1', r));
    base = `http://127.0.0.1:${server.address().port}`;
  });

  afterEach(async () => {
    await new Promise((r) => server.close(r));
  });

  const post = (path, fields) =>
    fetch(base + path, { method: 'POST', body: new URLSearchParams(fields), redirect: 'manual' });

  it('adds a book from the form and lists it as currently reading', async () => {
    const res = await post('/books', { title: 'Middlemarch', author: 'George Eliot', notes: 'Chapter 1' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const html = await (await fetch(base + '/')).text();
    const [reading, finished] = html.split('<h2>Finished</h2>');
    expect(reading).toContain('Middlemarch');
    expect(finished).not.toContain('Middlemarch');
  });

  it('marks a book finished and moves it to the finished list', async () => {
    const book = await store.add({ title: 'Beloved', author: 'Toni Morrison' });
    const res = await post(`/books/${book.id}/finish`, { back: 'home' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const html = await (await fetch(base + '/')).text();
    const [reading, finished] = html.split('<h2>Finished</h2>');
    expect(reading).not.toContain('Beloved');
    expect(finished).toContain('Beloved');
  });

  it('shows a book on its own shareable page with title, author and notes', async () => {
    const book = await store.add({ title: 'Emma', author: 'Jane Austen', notes: 'Line one\nLine two' });
    const res = await fetch(`${base}/books/${book.id}`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('<h1>Emma</h1>');
    expect(html).toContain('by Jane Austen');
    expect(html).toContain('Line one\nLine two');
    expect(html).toContain(`/books/${book.id}"`);
  });

  it('updates notes from the book page', async () => {
    const book = await store.add({ title: 'Emma' });
    const res = await post(`/books/${book.id}/notes`, { notes: 'Loved Mr Knightley' });
    expect(res.status).toBe(303);
    expect(store.get(book.id).notes).toBe('Loved Mr Knightley');
  });

  it('escapes whatever is typed in so it cannot inject HTML', async () => {
    const book = await store.add({ title: '<script>alert(1)</script>', author: '"x" & y', notes: '<b>hi</b>' });
    const html = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(html).not.toContain('<script>alert');
    expect(html).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(html).toContain('&quot;x&quot; &amp; y');
    expect(html).not.toContain('<b>hi</b>');
  });

  it('asks for a title and keeps what was typed', async () => {
    const res = await post('/books', { title: '   ', author: 'Someone' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Please give the book a title.');
    expect(html).toContain('value="Someone"');
    expect(store.list()).toEqual([]);
  });

  it('returns 404 for a book that does not exist', async () => {
    expect((await fetch(`${base}/books/nope123`)).status).toBe(404);
    expect((await post('/books/nope123/finish', {})).status).toBe(404);
    expect((await fetch(`${base}/elsewhere`)).status).toBe(404);
  });
});

